package com.profa.admin;import com.profa.user.*;import com.profa.teacher.*;import com.profa.document.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/v1/admin")@PreAuthorize("hasRole('ADMIN')")public class AdminController{final UserRepository users;final TeacherRepository teachers;final TeacherDocumentRepository docs;public AdminController(UserRepository u,TeacherRepository t,TeacherDocumentRepository d){users=u;teachers=t;docs=d;}@GetMapping("/stats")public Map<String,Object> stats(){return Map.of("users",users.count(),"teachers",teachers.count(),"pendingDocuments",docs.findAll().stream().filter(x->"PENDING".equals(x.getStatus())).count());}@GetMapping("/teachers/pending")public List<TeacherProfile> pending(){return teachers.findAll().stream().filter(x->!x.isVerified()).toList();}@PatchMapping("/teachers/{id}/verify")public TeacherProfile verify(@PathVariable UUID id){TeacherProfile p=teachers.findById(id).orElseThrow();p.setVerified(true);return teachers.save(p);}@GetMapping("/documents")public List<TeacherDocument> documents(){return docs.findAll();}@PatchMapping("/documents/{id}")public TeacherDocument document(@PathVariable UUID id,@RequestParam String status){TeacherDocument d=docs.findById(id).orElseThrow();d.setStatus(status);return docs.save(d);}}